    "\u7236\u5F15\u7528\u672A\u89E3\u6790": "R\xE9f\xE9rences parentales non r\xE9solues",
    "\u8D44\u6E90 {0}": "Ressources {0}",
    "\u6982\u89C8": "Aper\xE7u",
    "\u91CD\u65B0\u67E5\u8BE2\u8D44\u6E90\u8BE6\u60C5": "Recharger les d\xE9tails de la ressource",
