    "{0}\uFF1B\u4E8B\u4EF6\u53D7\u670D\u52A1\u7AEF\u4FDD\u7559\u65F6\u95F4\u548C\u6743\u9650\u9650\u5236\u3002": "{0}; \u0437\u0430\u043B\u0435\u0436\u043D\u043E \u0432\u0456\u0434 \u0443\u0442\u0440\u0438\u043C\u0430\u043D\u043D\u044F \u0441\u0435\u0440\u0432\u0435\u0440\u0430 \u0442\u0430 \u0434\u043E\u0437\u0432\u043E\u043B\u0456\u0432.",
    "\u5DF2\u6392\u9664 {0} \u6761\u4E0D\u5339\u914D\u8D44\u6E90\u8EAB\u4EFD\u7684\u4E8B\u4EF6\u3002": "\u0412\u0438\u043A\u043B\u044E\u0447\u0435\u043D\u043E \u043F\u043E\u0434\u0456\u0457 {0} \u0437 \u0456\u043D\u0448\u0438\u043C \u0456\u0434\u0435\u043D\u0442\u0438\u0444\u0456\u043A\u0430\u0442\u043E\u0440\u043E\u043C \u0440\u0435\u0441\u0443\u0440\u0441\u0443.",
    "\u5F53\u524D\u67E5\u8BE2\u8303\u56F4\u6CA1\u6709\u4E8B\u4EF6\uFF1B\u4E0D\u4EE3\u8868\u6CA1\u6709\u53D1\u751F\u8FC7\u5F02\u5E38\u3002": "\u041D\u0435\u043C\u0430\u0454 \u043F\u043E\u0434\u0456\u0439 \u0443 \u043F\u043E\u0442\u043E\u0447\u043D\u0456\u0439 \u043E\u0431\u043B\u0430\u0441\u0442\u0456 \u0437\u0430\u043F\u0438\u0442\u0443; \u0446\u0435 \u043D\u0435 \u0434\u043E\u0432\u043E\u0434\u0438\u0442\u044C, \u0449\u043E \u0456\u043D\u0446\u0438\u0434\u0435\u043D\u0442\u0456\u0432 \u043D\u0435 \u0431\u0443\u043B\u043E.",
    "\u539F\u56E0\u672A\u77E5": "\u041F\u0440\u0438\u0447\u0438\u043D\u0430 \u043D\u0435\u0432\u0456\u0434\u043E\u043C\u0430",
    "\u9996\u6B21 {0} \xB7 \u6700\u8FD1 {1} \xB7 \u6B21\u6570 {2} \xB7 \u6765\u6E90 {3}": "\u041F\u0435\u0440\u0448\u0438\u0439 {0} \xB7 \u041E\u0441\u0442\u0430\u043D\u043D\u0456\u0439 {1} \xB7 \u041A\u0456\u043B\u044C\u043A\u0456\u0441\u0442\u044C {2} \xB7 \u0414\u0436\u0435\u0440\u0435\u043B\u043E {3}",
    "{0} \xB7 {1} \xB7 {2} \xB7 Ready {3} \xB7 \u91CD\u542F {4} \xB7 {5} {6}": "{0} \xB7 {1} \xB7 {2} \xB7 \u0413\u043E\u0442\u043E\u0432\u0438\u0439 {3} \xB7 \u041F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u043A {4} \xB7 {5} {6}",
