    "\u8D44\u6E90\u8BE6\u60C5\u4E0E\u4E8B\u4EF6": "\u0414\u0435\u0442\u0430\u043B\u0456 \u0440\u0435\u0441\u0443\u0440\u0441\u0443 \u0442\u0430 \u043F\u043E\u0434\u0456\u0457",
    "\u67E5\u8BE2\u8D44\u6E90\u6811\uFF08\u53EA\u8BFB\u540E\u53F0\u4EFB\u52A1\uFF09": "\u0427\u0438\u0442\u0430\u0442\u0438 \u0434\u0435\u0440\u0435\u0432\u043E \u0440\u0435\u0441\u0443\u0440\u0441\u0456\u0432 (\u0444\u043E\u043D\u043E\u0432\u0435 \u0437\u0430\u0432\u0434\u0430\u043D\u043D\u044F)",
    "\u67E5\u8BE2\u5E94\u7528\u4E8B\u4EF6": "\u0427\u0438\u0442\u0430\u0442\u0438 \u043F\u043E\u0434\u0456\u0457 \u043F\u0440\u043E\u0433\u0440\u0430\u043C\u0438",
    "\u67E5\u8BE2\u5B64\u7ACB\u8D44\u6E90\u68C0\u6D4B\u914D\u7F6E": "\u041F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u0438 \u043F\u0430\u0440\u0430\u043C\u0435\u0442\u0440\u0438 \u043C\u043E\u043D\u0456\u0442\u043E\u0440\u0438\u043D\u0433\u0443 \u0441\u0438\u0440\u0456\u0442",
    "\u7B5B\u9009\u8D44\u6E90\uFF08\u540D\u79F0 / Namespace / Kind / Health / orphaned\uFF09": "\u0424\u0456\u043B\u044C\u0442\u0440\u0443\u0432\u0430\u0442\u0438 \u0440\u0435\u0441\u0443\u0440\u0441\u0438 (\u0456\u043C'\u044F / \u043F\u0440\u043E\u0441\u0442\u0456\u0440 \u0456\u043C\u0435\u043D / \u0432\u0438\u0434 / \u0437\u0434\u043E\u0440\u043E\u0432'\u044F / \u043E\u0441\u0438\u0440\u043E\u0442\u0456\u043B\u0456)",
    "\u5E94\u7528\u8D44\u6E90\u6811": "\u0414\u0435\u0440\u0435\u0432\u043E \u0440\u0435\u0441\u0443\u0440\u0441\u0456\u0432 \u043F\u0440\u043E\u0433\u0440\u0430\u043C\u0438",
    "\u5C1A\u672A\u67E5\u8BE2\u8D44\u6E90\u6811": "\u0414\u0435\u0440\u0435\u0432\u043E \u0440\u0435\u0441\u0443\u0440\u0441\u0456\u0432 \u043D\u0435 \u0437\u0430\u0432\u0430\u043D\u0442\u0430\u0436\u0435\u043D\u043E",
    "\u5F53\u524D\u5FEB\u7167\u6CA1\u6709\u5339\u914D\u8D44\u6E90\uFF1B\u4E0D\u7B49\u4E8E\u96C6\u7FA4\u4E2D\u6CA1\u6709\u8D44\u6E90": "\u041D\u0430 \u0446\u044C\u043E\u043C\u0443 \u0437\u043D\u0456\u043C\u043A\u0443 \u043D\u0435\u043C\u0430\u0454 \u0432\u0456\u0434\u043F\u043E\u0432\u0456\u0434\u043D\u0438\u0445 \u0440\u0435\u0441\u0443\u0440\u0441\u0456\u0432; \u043D\u0435 \u0454 \u0434\u043E\u043A\u0430\u0437\u043E\u043C \u0442\u043E\u0433\u043E, \u0449\u043E \u043A\u043B\u0430\u0441\u0442\u0435\u0440 \u0457\u0445 \u043D\u0435 \u043C\u0430\u0454",
    "\u672A\u77E5\u7248\u672C": "\u041D\u0435\u0432\u0456\u0434\u043E\u043C\u0430 \u0432\u0435\u0440\u0441\u0456\u044F",
    "\u65E0\u5065\u5EB7\u8BE6\u60C5": "\u0411\u0435\u0437 \u043F\u043E\u0434\u0440\u043E\u0431\u0438\u0446\u044C \u043F\u0440\u043E \u0437\u0434\u043E\u0440\u043E\u0432'\u044F",
    "{0}/{1} \xB7 {2} \xB7 {3} \u4E2A\u7236\u8282\u70B9": "{0}/{1} \xB7 {2} \xB7 {3} \u0431\u0430\u0442\u044C\u043A\u0438",
    "\u5B64\u7ACB\u8D44\u6E90": "\u041E\u0441\u0438\u0440\u043E\u0442\u0456\u043B\u0430",
