    " \xB7 \u7236\u5F15\u7528\u672A\u89E3\u6790": " \xB7 \u041D\u0435\u0432\u0438\u0440\u0456\u0448\u0435\u043D\u0456 \u0440\u0435\u043A\u043E\u043C\u0435\u043D\u0434\u0430\u0446\u0456\u0457 \u0431\u0430\u0442\u044C\u043A\u0456\u0432",
    "\u6B63\u5728\u67E5\u8BE2\u8D44\u6E90\u6811\u2026": "\u0427\u0438\u0442\u0430\u043D\u043D\u044F \u0434\u0435\u0440\u0435\u0432\u0430 \u0440\u0435\u0441\u0443\u0440\u0441\u0456\u0432\u2026",
    "{0} \u4E2A\u8D44\u6E90 \xB7 \u5B64\u7ACB\u8D44\u6E90\u76D1\u6D4B {1}": "\u0420\u0435\u0441\u0443\u0440\u0441\u0438 {0} \xB7 \u041C\u043E\u043D\u0456\u0442\u043E\u0440\u0438\u043D\u0433 \u0441\u0438\u0440\u0456\u0442: {1}",
    "\u670D\u52A1\u7AEF\u8FD4\u56DE\u4E86\u5B64\u7ACB\u8282\u70B9": "\u0441\u0435\u0440\u0432\u0435\u0440 \u043F\u043E\u0432\u0435\u0440\u043D\u0443\u0432 \u0437\u0430\u0433\u0443\u0431\u043B\u0435\u043D\u0456 \u0432\u0443\u0437\u043B\u0438",
    "\u672A\u77E5\uFF1B\u7A7A\u5217\u8868\u4E0D\u80FD\u8BC1\u660E\u5DF2\u5F00\u542F\u68C0\u6D4B\uFF0C\u8BF7\u67E5\u8BE2 Project \u914D\u7F6E": "\u043D\u0435\u0432\u0456\u0434\u043E\u043C\u0438\u0439; \u043F\u043E\u0440\u043E\u0436\u043D\u0456\u0439 \u0441\u043F\u0438\u0441\u043E\u043A \u043D\u0435 \u043F\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0443\u0454, \u0449\u043E \u043C\u043E\u043D\u0456\u0442\u043E\u0440\u0438\u043D\u0433 \u0443\u0432\u0456\u043C\u043A\u043D\u0435\u043D\u043E. \u041F\u0440\u043E\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F \u043F\u0440\u043E\u0435\u043A\u0442\u0443",
    "\u62D3\u6251\u8B66\u793A\uFF1A{0}\uFF1B\u591A\u7236\u5173\u7CFB\u4FDD\u7559\uFF0C\u73AF\u8DEF\u8282\u70B9\u53EA\u5C55\u793A\u4E00\u6B21\u3002": "\u041F\u043E\u043F\u0435\u0440\u0435\u0434\u0436\u0435\u043D\u043D\u044F \u0449\u043E\u0434\u043E \u0442\u043E\u043F\u043E\u043B\u043E\u0433\u0456\u0457: {0}; \u043A\u0456\u043B\u044C\u043A\u0430 \u0431\u0430\u0442\u044C\u043A\u0456\u0432 \u0437\u0431\u0435\u0440\u0456\u0433\u0430\u044E\u0442\u044C\u0441\u044F, \u0432\u0443\u0437\u043B\u0438 \u0446\u0438\u043A\u043B\u0443 \u0437'\u044F\u0432\u043B\u044F\u044E\u0442\u044C\u0441\u044F \u043E\u0434\u0438\u043D \u0440\u0430\u0437.",
    "\u8D44\u6E90\u6811\u67E5\u8BE2\u5931\u8D25\uFF1B\u4E0D\u662F\u7A7A\u7ED3\u679C\u3002": "\u041F\u043E\u043C\u0438\u043B\u043A\u0430 \u0437\u0430\u043F\u0438\u0442\u0443 \u0434\u0435\u0440\u0435\u0432\u0430 \u0440\u0435\u0441\u0443\u0440\u0441\u0456\u0432; \u0446\u0435 \u043D\u0435 \u043F\u043E\u0440\u043E\u0436\u043D\u0456\u0439 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442.",
    "\u6B63\u5728\u67E5\u8BE2\u5E94\u7528\u4E8B\u4EF6\u2026": "\u0427\u0438\u0442\u0430\u043D\u043D\u044F \u043F\u043E\u0434\u0456\u0439 \u043F\u0440\u043E\u0433\u0440\u0430\u043C\u0438\u2026",
    "\u5E94\u7528\u4E8B\u4EF6\u67E5\u8BE2\u5931\u8D25\uFF1B\u4E0D\u662F\u6CA1\u6709\u4E8B\u4EF6\u3002": "\u041F\u043E\u043C\u0438\u043B\u043A\u0430 \u0437\u0430\u043F\u0438\u0442\u0443 \u043F\u043E\u0434\u0456\u0457 \u043F\u0440\u043E\u0433\u0440\u0430\u043C\u0438; \u0446\u0435 \u043D\u0435 \u043E\u0437\u043D\u0430\u0447\u0430\u0454, \u0449\u043E \u043F\u043E\u0434\u0456\u0439 \u043D\u0435\u043C\u0430\u0454.",
    "Project \u672A\u5F00\u542F\u5B64\u7ACB\u8D44\u6E90\u68C0\u6D4B\uFF1B\u6CA1\u6709\u5B64\u7ACB\u8282\u70B9\u4E0D\u662F\u6CA1\u6709\u5B64\u7ACB\u8D44\u6E90\u7684\u8BC1\u660E\u3002": "\u041C\u043E\u043D\u0456\u0442\u043E\u0440\u0438\u043D\u0433 \u0441\u0438\u0440\u0456\u0442 \u0432\u0438\u043C\u043A\u043D\u0435\u043D\u043E \u0434\u043B\u044F \u0446\u044C\u043E\u0433\u043E \u043F\u0440\u043E\u0435\u043A\u0442\u0443; \u0432\u0456\u0434\u0441\u0443\u0442\u043D\u0456\u0441\u0442\u044C \u0437\u0430\u0433\u0443\u0431\u043B\u0435\u043D\u0438\u0445 \u0432\u0443\u0437\u043B\u0456\u0432 \u043D\u0435 \u0454 \u0434\u043E\u043A\u0430\u0437\u043E\u043C \u0432\u0456\u0434\u0441\u0443\u0442\u043D\u043E\u0441\u0442\u0456 \u0437\u0430\u0433\u0443\u0431\u043B\u0435\u043D\u0438\u0445 \u0440\u0435\u0441\u0443\u0440\u0441\u0456\u0432.",
    "Project \u5DF2\u5F00\u542F\u5B64\u7ACB\u8D44\u6E90\u68C0\u6D4B\uFF1Bwarn={0}\u3002": "\u0423\u0432\u0456\u043C\u043A\u043D\u0435\u043D\u043E \u043C\u043E\u043D\u0456\u0442\u043E\u0440\u0438\u043D\u0433 \u0432\u0442\u0440\u0430\u0442\u0438 \u043F\u0440\u043E\u0435\u043A\u0442\u0443; \u043F\u043E\u043F\u0435\u0440\u0435\u0434\u0438\u0442\u0438={0}.",
    "\u5B64\u7ACB\u8D44\u6E90\u68C0\u6D4B\u914D\u7F6E\u672A\u77E5\uFF1BProject \u914D\u7F6E\u8BFB\u53D6\u5931\u8D25\u3002": "\u041F\u0430\u0440\u0430\u043C\u0435\u0442\u0440\u0438 \u043C\u043E\u043D\u0456\u0442\u043E\u0440\u0438\u043D\u0433\u0443 \u0441\u0438\u0440\u0456\u0442 \u043D\u0435\u0432\u0456\u0434\u043E\u043C\u0456; \u043D\u0435 \u0432\u0434\u0430\u043B\u043E\u0441\u044F \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u0438 \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F \u043F\u0440\u043E\u0435\u043A\u0442\u0443.",
