    "\u8BED\u8A00": "J\u0119zyk",
    "\u8DDF\u968F\u5BBF\u4E3B": "Pod\u0105\u017Caj za gospodarzem",
    "\u89C6\u56FE\u5BC6\u5EA6": "G\u0119sto\u015B\u0107",
    "\u7D27\u51D1": "Kompaktowy",
    "\u5BBD\u677E": "Wygodne",
